Object.assign(window.LIT_VERSES,{"mutanabbi-azm-003":{"id":"mutanabbi-azm-003","poemId":"ala-qadr-ahl-al-azm","order":3,"first":"يُكَلِّفُ سَيفُ الدَولَةِ الجَيشَ هَمَّهُ","second":"وَقَد عَجَزَت عَنهُ الجُيوشُ الخَضارِمُ","meaning":"يحمّل سيف الدولة جيشه أعمالًا على قدر همته هو، وهي همة يبالغ المتنبي في رفعها حتى يجعل الجيوش العظيمة الكثيرة عاجزة عن بلوغ مداها.","vocabulary":[{"term":"همّه","text":"ما تتجه إليه همته من الغزو والعمل الكبير."},{"term":"الخضارم","text":"جمع خضرم؛ الكثير العظيم من كل شيء. يشرح الواحدي اللفظة بهذا المعنى."}],"syntax":["«سيف الدولة» فاعل «يكلف»، و«الجيش» مفعوله الأول، و«همّه» المفعول الثاني: يكلف الجيش ما تقتضيه همته.","الجملة الثانية حالية في أثرها: وهو يكلف جيشه ذلك مع أن جيوشًا عظيمة قد عجزت عنه."],"morphology":["«يكلّف» فعل مزيد بالتضعيف من «كلِف/كلّف»، وفي التضعيف معنى التعدية: يجعل الجيش متحملًا لما يريده همّه.","«الخضارم» جمع «خِضْرَم»، ويستعمل في الكثير العظيم؛ فصيغة الجمع نفسها تعزز معنى كثرة الجيوش التي عجزت.","«همّه» مصدر أُسند إليه فعل التكليف على سبيل المجاز، فصار المعنى النفسي كأنه قوة فاعلة مستقلة."],"rhetoric":{"thesis":"هنا يبدأ التطبيق الفعلي للحكمة: لا يقول المتنبي إن سيف الدولة عظيم فقط؛ بل يعيد صياغة معنى البيت الأول في صورة عملية فيها قائد وجيش ومهمة تتجاوز الطاقة المعتادة.","devices":[{"title":"من التجريد إلى المشهد","text":"انتقلنا من «أهل العزم» المجهولين إلى اسم محدد: سيف الدولة. هذا التحول يمنع المقدمة من أن تبقى حكمة معلقة ويجعلها جزءًا من بنية المدح."},{"title":"مفارقة المفرد والجمع","text":"جيش واحد يكلّفه سيف الدولة همته، ثم «الجيوش» بالجمع تعجز عن تلك الهمة. الفرق العددي يخدم المبالغة في رفع معيار الممدوح."},{"title":"جعل الهمة تكليفًا","text":"الهمة معنى نفسي، لكن البيت يجعلها شيئًا يُحمَّل على الجيش. بهذا تتحول صفة داخلية في القائد إلى عبء عملي يقيس طاقة الرجال."},{"title":"المبالغة الوظيفية","text":"المبالغة هنا ليست منفصلة عن الحجة؛ إنها تجيب عن السؤال الذي صنعه المطلع: ما صورة «العزائم على قدر أهل العزم»؟ هذه هي الصورة."}],"connection":"البيت الرابع سيكشف نتيجة أخرى لعظمة المعيار عند سيف الدولة: إنه يطلب من الناس ما يجده في نفسه، ولذلك يبدو طلبه فوق طاقة البشر."},"prosody":{"meter":"البحر الطويل","rhyme":"الروي ميم مضمومة","note":"تكرار الجيم والشين والخاء والضاد في «الجيش / الجيوش / الخضارم» يمنح الشطر الثاني ثقلاً صوتيًا يلائم معنى الكثرة والعظمة، من غير أن نجعل الصوت وحده دليل المعنى."},"context":"أول ذكر مباشر لسيف الدولة في القصيدة. عنده تنتقل المقدمة من الحكمة إلى المدح الحربي.","variants":[{"reading":"الجيوش الخضارم","status":"المعتمد هنا","note":"الواحدي يصرح بأن هذه الرواية هي الصحيحة عنده، وينبه إلى رواية أخرى ربطت «الخضارم» بالبحور."}],"sourceIds":["wahidi-274","barquqi-162-170"]},"mutanabbi-azm-004":{"id":"mutanabbi-azm-004","poemId":"ala-qadr-ahl-al-azm","order":4,"first":"وَيَطلُبُ عِندَ الناسِ ما عِندَ نَفسِهِ","second":"وَذلِكَ ما لا تَدَّعيهِ الضَراغِمُ","meaning":"يقيس سيف الدولة الناس على ما يجده في نفسه من شجاعة وبأس، فيطلب منهم مستوى بالغًا من الإقدام؛ ويبالغ المتنبي حتى يقول إن الأسود نفسها لا تدعي بلوغ هذا المقدار.","vocabulary":[{"term":"الضراغم","text":"جمع ضرغم، وهو الأسد؛ واستحضاره هنا لاستدعاء أقصى صورة مألوفة للشجاعة والقوة."},{"term":"ما عند نفسه","text":"ما استقر في نفسه من الشجاعة والهمة والبأس، لا مجرد شيء مادي «عنده»."}],"syntax":["المقابلة بين «عند الناس» و«عند نفسه» تبني الجملة على معيارين متواجهين.","اسم الإشارة «ذلك» يلخص ما سبق كله ويجعله موضوع الحكم التالي: مستوى لا تدعيه الضراغم."],"morphology":["«تدّعيه» من «ادّعى»؛ وفي الصيغة معنى نسبة الشيء إلى النفس والمطالبة به، وهو أنسب من مجرد «تفعله» لأن البيت يتحدث عن جرأة لا تزعمها حتى الأسود.","«الضراغم» جمع «ضِرغام»، وهو الأسد. اختيار الجمع لا المفرد يرفع سقف المقارنة: حتى جنس الأسود في جمعه لا يدّعي ذلك.","التكرار الصرفي في «عند الناس / عند نفسه» ليس اشتقاقًا، لكنه يثبت وحدة البنية التي يقارن داخلها بين الخارج والذات."],"rhetoric":{"thesis":"قوة البيت في بناء معيار مستحيل تقريبًا: سيف الدولة لا يطلب من الناس الحد المعتاد، بل يطلب منهم نسخة من القوة التي يجدها في نفسه.","devices":[{"title":"تناظر الموضعين","text":"«عند الناس / عند نفسه» تضع الخارج والداخل في ميزان واحد. المشكلة ليست في أن الناس لا يعملون، بل في أن المقياس الذي يقيسهم به الممدوح مأخوذ من نفسه الاستثنائية."},{"title":"الأسد كحد أقصى","text":"الضراغم ليست وصفًا عابرًا؛ إنها معيار ثقافي للشجاعة. فإذا كانت الأسود لا تدعي ذلك، فالمبالغة ترفع الممدوح فوق النموذج الحيواني الذي اعتادت العربية اتخاذه غاية في البأس."},{"title":"الإبهام ثم التفسير","text":"«ما عند نفسه» عبارة عامة لا تفصل الصفات واحدة واحدة. يأتي «الضراغم» ليحدد جهة القراءة: الشجاعة والبأس في المقام الحربي."},{"title":"إغلاق المقطع الأول","text":"بهذا البيت تكتمل الحجة: عظمة الهمة → عظمة الفعل → عجز الجيوش → معيار لا تبلغه الأسود. بعد ذلك يستطيع الشاعر الانتقال إلى صورة حسية للحرب."}],"connection":"البيتان الخامس والسادس لا يواصلان المدح بالتقرير، بل يقدمان دليلًا تصويريًا قاسيًا على كثرة الوقائع والقتلى: النسور وسلاح سيف الدولة."},"prosody":{"meter":"البحر الطويل","rhyme":"الروي ميم مضمومة","note":"البيت أقل اعتمادًا على التقابل الصريح من سابقه، لكنه يحتفظ بتناظر «عند... عند...» ثم ينتهي بكلمة ثقيلة الدلالة «الضراغم»."},"context":"خاتمة المقطع الذي يطبق حكمة المطلع على سيف الدولة قبل الانتقال إلى مشاهد الحرب.","sourceIds":["wahidi-274","barquqi-162-170"]}});